def solve():
    n, k, p, x, y = map(int, input().split())
    a = list(map(int, input().split()))

    remaining = n - k
    current_sum = sum(a)
    current_median = sorted(a)[(n - 1) // 2]

    def check_median(median):
        lower = [m for m in a if m < median]
        upper = [m for m in a if m > median]
        while len(lower) < (n + 1) // 2:
            lower.append(median)
        while len(upper) < n // 2:
            upper.append(median)
        return sorted(lower + upper)[(n - 1) // 2]

    for _ in range(remaining):
        if current_sum >= x:
            print(-1)
            return

        for mark in range(p, 0, -1):
            new_sum = current_sum + mark
            if new_sum > x:
                continue

            new_median = check_median(mark)
            if new_median >= y:
                current_sum = new_sum
                current_median = new_median
                a.append(mark)
                break
        else:
            print(-1)
            return

    print(*a[k:])

solve()
